from pathlib import Path
source = '"""zemu-flask 对拍测试:用真 itsdangerous/Flask 出 cookie,校验 CLI 各命令。\n\n用法(需先 pip install itsdangerous flask 到虚拟环境):\n    python tests/test_vectors.py\n"""\nimport base64\nimport hashlib\nimport hmac\nimport json\nimport os\nimport subprocess\nimport sys\nimport time\n\nfrom flask.sessions import session_json_serializer\nfrom itsdangerous import URLSafeTimedSerializer\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nROOT = os.path.dirname(HERE)\nTOOL = os.path.join(ROOT, "tests", "perf_research_20260907", "baseline.exe")\nWORDLIST = os.path.join(HERE, "wl-test.txt")\n\n\ndef make_serializer(secret: str) -> URLSafeTimedSerializer:\n    # 与 Flask 3.1 get_signing_serializer 完全一致的构造\n    return URLSafeTimedSerializer(\n        secret_key=secret,\n        salt="cookie-session",\n        serializer=session_json_serializer,\n        signer_kwargs={"key_derivation": "hmac", "digest_method": hashlib.sha1},\n    )\n\n\ndef run(*args: str) -> subprocess.CompletedProcess:\n    return subprocess.run([TOOL, *args], capture_output=True, text=True, encoding="utf-8")\n\n\nfails = 0\n\n\ndef check(name: str, ok: bool, extra: str = "") -> None:\n    global fails\n    print(("PASS" if ok else "FAIL"), name, extra)\n    if not ok:\n        fails += 1\n\n\n# --- 1. decode:Python 签 → 工具解 ---\ncases = [\n    {"username": "admin", "uid": 1},\n    {"a": [1, True, None], "中文": "键\\n值", "f": 1.5},\n    {},\n]\nfor i, obj in enumerate(cases):\n    cookie = make_serializer("secret123").dumps(obj)\n    r = run("flask", "decode", "--cookie", cookie)\n    got = json.loads(r.stdout.strip())\n    check(f"decode#{i}", got == obj, r.stdout.strip()[:80])\n\n# --- 2. verify:有效/无效密钥 ---\ncookie = make_serializer("s3cr3t-key").dumps({"user": "test"})\nr = run("flask", "verify", "--cookie", cookie, "--secret", "s3cr3t-key")\ncheck("verify-good", r.returncode == 0 and r.stdout.strip() == "valid")\nr = run("flask", "verify", "--cookie", cookie, "--secret", "wrong")\ncheck("verify-bad", r.returncode == 1 and r.stdout.strip() == "invalid")\n\n# --- 2b. 压缩 timed cookie:保留前导点参与验签,覆盖字典和掩码路径 ---\ncompressed_obj = {"data": "A" * 500}\ncompressed_cookie = make_serializer("cmp7").dumps(compressed_obj)\ncheck("compressed-fixture", compressed_cookie.startswith("."))\nr = run("flask", "decode", "--cookie", compressed_cookie)\ncheck("compressed-decode", r.returncode == 0 and json.loads(r.stdout) == compressed_obj)\nfor secret, expected in (("cmp7", "valid"), ("wrong", "invalid")):\n    r = run("flask", "verify", "--cookie", compressed_cookie, "--secret", secret)\n    check(f"compressed-verify-{expected}",\n          r.returncode == (0 if expected == "valid" else 1) and r.stdout.strip() == expected)\n\n# 去掉压缩标记后结构仍合法,但原签名必须失效。\nr = run("flask", "verify", "--cookie", compressed_cookie[1:], "--secret", "cmp7")\ncheck("compressed-marker-authenticated", r.returncode == 1 and r.stdout.strip() == "invalid")\n\nwith open(WORDLIST, "w", encoding="utf-8") as f:\n    f.write("wrong\\ncmp7\\nanother\\n")\ntry:\n    for engine in ("cpu", "gpu", "auto"):\n        for mode, value in (("--wordlist", WORDLIST), ("--mask", "cmp?d")):\n            r = run("flask", "crack", "--cookie", compressed_cookie, mode, value,\n                    "--engine", engine, "--threads", "2")\n            check(f"compressed-crack-{engine}-{mode[2:]}",\n                  r.returncode == 0 and r.stdout.strip() == "cmp7", r.stderr.strip()[-160:])\nfinally:\n    os.unlink(WORDLIST)\n\n# 拒绝空载荷/时间戳/签名和额外分隔符,包括具有正确 HMAC 的畸形结构。\ndef signed_value(value):\n    dk = hmac.new(b"cmp7", b"cookie-session", hashlib.sha1).digest()\n    sig = base64.urlsafe_b64encode(hmac.new(dk, value.encode(), hashlib.sha1).digest())\n    return value + "." + sig.rstrip(b"=").decode()\n\nmalformed_cookies = [signed_value(v) for v in\n                     (".AAAA", "..AAAA", "YWJj.", ".YWJj.", "YWJj.extra.AAAA",\n                      ".YWJj.extra.AAAA")]\nmalformed_cookies.extend(("YWJj.AAAA.", ".YWJj.AAAA."))\nfor i, malformed in enumerate(malformed_cookies):\n    for action, extra in (("verify", ["--secret", "cmp7"]),\n                          ("crack", ["--mask", "cmp7", "--engine", "cpu"])):\n        r = run("flask", action, "--cookie", malformed, *extra)\n        check(f"cookie-structure-{i}-{action}", r.returncode == 1 and not r.stdout.strip())\n\n# --- 2c. 可选时间校验:默认仍只验签,签名错误优先于时间错误 ---\ndef timed_cookie(timestamp, compressed=False):\n    source = compressed_cookie if compressed else cookie\n    payload = source.rsplit(".", 2)[0]\n    value = payload + "." + timestamp\n    dk = hmac.new(b"age-key", b"cookie-session", hashlib.sha1).digest()\n    sig = base64.urlsafe_b64encode(hmac.new(dk, value.encode(), hashlib.sha1).digest())\n    return value + "." + sig.rstrip(b"=").decode()\n\n\ndef encoded_time(value):\n    return base64.urlsafe_b64encode(value.to_bytes(8, "big").lstrip(b"\\0") or b"\\0").rstrip(b"=").decode()\n\n\nnow = int(time.time())\nfor name, ts, options, expected in [\n    ("default-old", encoded_time(now - 7200), [], "valid"),\n    ("fresh", encoded_time(now - 10), ["--max-age", "3600"], "valid"),\n    ("expired", encoded_time(now - 7200), ["--max-age", "3600"], "expired"),\n    ("zero", encoded_time(now - 10), ["--max-age", "0"], "expired"),\n    ("future", encoded_time(now + 3600), ["--max-age", "3600"], "future"),\n    ("invalid", "!bad!", ["--max-age", "3600"], "invalid-timestamp"),\n    ("oversize", base64.urlsafe_b64encode(b"a" * 9).decode(), ["--max-age", "3600"], "invalid-timestamp"),\n    ("uint64-max", encoded_time(2**64 - 1), ["--max-age", str(2**63 - 1)], "future"),\n    ("legacy", encoded_time(now - 1293840000 - 10), ["--max-age", "3600", "--legacy"], "valid"),\n    ("legacy-overflow", encoded_time(2**64 - 1), ["--max-age", "3600", "--legacy"], "invalid-timestamp"),\n]:\n    for compressed in (False, True):\n        c = timed_cookie(ts, compressed)\n        r = run("flask", "verify", "--cookie", c, "--secret", "age-key", *options)\n        check(f"max-age-{name}-{compressed}", r.stdout.strip() == expected and\n              r.returncode == (0 if expected == "valid" else 1))\n\nr = run("flask", "verify", "--cookie", timed_cookie("!bad!"),\n        "--secret", "wrong", "--max-age", "3600")\ncheck("max-age-signature-first", r.returncode == 1 and r.stdout.strip() == "invalid")\nfor value in ("", "abc", "1.5", "8x", "-1", "9223372036854775808"):\n    r = run("flask", "verify", "--cookie", cookie, "--secret", "k", "--max-age", value)\n    check(f"max-age-argument-{value!r}", r.returncode == 2 and "--max-age" in r.stderr)\nr = run("flask", "verify", "--cookie", cookie, "--secret", "k", "--max-age")\ncheck("max-age-missing", r.returncode == 2)\nr = run("flask", "decode", "--cookie", cookie, "--max-age", "3600")\ncheck("max-age-wrong-command", r.returncode == 2)\n\n# 一行只能有一个 JSON 值;空白允许,原始 NUL 也不能掩盖尾随内容。\nvalid_command = json.dumps(["flask", "decode", "--cookie", make_serializer("k").dumps({"serve": 1})])\nfor suffix in (" garbage", " []", " null", "\\0garbage", "\\0"):\n    r = subprocess.run([TOOL, "serve"], input=valid_command + suffix + "\\n" + valid_command + " \\t\\r\\n",\n                       capture_output=True, text=True, encoding="utf-8", timeout=15)\n    lines = r.stdout.splitlines()\n    markers = [line for line in lines if line.startswith("<<<zk-rc=")]\n    check(f"serve-trailing-{suffix!r}", r.returncode == 0 and\n          markers == ["<<<zk-rc=2>>>", "<<<zk-rc=0>>>"] and lines.count(\'{"serve":1}\') == 1)\n\n# --- 3. sign:工具签 → Python 验 ---\nser = make_serializer("my-secret")\nfor i, obj in enumerate(cases):\n    r = run("flask", "sign", "--secret", "my-secret", "--json", json.dumps(obj))\n    c = r.stdout.strip()\n    try:\n        back = ser.loads(c)\n        ok = back == obj\n        extra = ""\n    except Exception as e:\n        ok, extra = False, f"{type(e).__name__}: {e}"\n    check(f"sign#{i}", ok, extra)\n\n# --- 4. sign --legacy:ts 以 2011-01-01(EPOCH=1293840000)为基准,签名手算复现 ---\ndef b64d(s: str) -> bytes:\n    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))\n\n\nr = run("flask", "sign", "--secret", "k", "--json", \'{"x":1}\', "--legacy")\nparts = r.stdout.strip().split(".")\nts = int.from_bytes(b64d(parts[1]), "big")\ndk = hmac.new(b"k", b"cookie-session", hashlib.sha1).digest()\nexpect_sig = base64.urlsafe_b64encode(\n    hmac.new(dk, f"{parts[0]}.{parts[1]}".encode(), hashlib.sha1).digest()\n).rstrip(b"=").decode()\ncheck("sign-legacy",\n      len(parts) == 3 and abs(ts - (time.time() - 1293840000)) < 60 and parts[2] == expect_sig,\n      r.stdout.strip()[:80])\n\n# --- 5. sign 边界:重复 key 后者覆盖(对齐 Python json.loads),超深嵌套拒绝 ---\nr = run("flask", "sign", "--secret", "my-secret", "--json", \'{"a":1,"a":2}\')\ncheck("sign-dupkey", ser.loads(r.stdout.strip()) == {"a": 2})\nr = run("flask", "sign", "--secret", "s", "--json", "[" * 300 + "1" + "]" * 300)\ncheck("sign-deep-nest", r.returncode == 1)\n\n# --- 5b. sign 健壮性:截断 \\u 转义(防 hex4 越界读)与非法 UTF-8(jsonEscape 强校验)---\nr = run("flask", "sign", "--secret", "s", "--json", \'{"x":"\\\\u12\')\ncheck("sign-trunc-u", r.returncode == 1)\n# 非法 UTF-8 字节(0xFF)经 serve 模式按原始字节喂入,须拒绝签名(rc=1)\npayload = b\'["flask", "sign", "--secret", "s", "--json", "{\\\\"x\\\\":\\\\"\\xff\\\\"}"]\\n\'\nr = subprocess.run([TOOL, "serve"], input=payload, capture_output=True)\ncheck("sign-bad-utf8", b"<<<zk-rc=1>>>" in r.stdout)\n\n# --- 6. crack 字典:CPU 与 GPU 双引擎 ---\ncookie = make_serializer("dragon").dumps({"flag": "ctf{demo}"})\nwith open(WORDLIST, "w", encoding="utf-8") as f:\n    f.write("\\n".join(["123456", "password", "dragon", "qwerty"]) + "\\n")\nfor engine in ("cpu", "gpu", "auto"):\n    r = run("flask", "crack", "--cookie", cookie, "--wordlist", WORDLIST,\n            "--threads", "4", "--engine", engine)\n    check(f"crack-dict-{engine}", r.returncode == 0 and r.stdout.strip() == "dragon",\n          r.stderr.strip().splitlines()[-1] if r.stderr else "")\nos.unlink(WORDLIST)\n\n# --- 6b. hybrid 字典含超长词:GPU 命中后不得再过 idxMap(回归:曾双重映射输出错误词) ---\ncookie = make_serializer("target123").dumps({"x": 1})\nwith open(WORDLIST, "w", encoding="utf-8") as f:\n    f.write("a" * 40 + "\\n")        # 超 stride=32,GPU 打包跳过 → idxMap 非恒等\n    f.write("target123\\n")          # 原下标 1;GPU 命中 packed 0,映回原下标 1\n    for i in range(2_000_000):      # 填充词拖住 CPU 侧(单线程从尾部降序吃块),让 GPU 先命中\n        f.write(f"zz{i:07x}\\n")\nenv = dict(os.environ, ZK_GPUTHRESH="1", ZK_NOPROG="1")  # 强制小字典也走 GPU+CPU 混合\nr = subprocess.run([TOOL, "flask", "crack", "--cookie", cookie, "--wordlist", WORDLIST,\n                    "--engine", "auto", "--threads", "1"],\n                   capture_output=True, text=True, encoding="utf-8", env=env)\ncheck("crack-dict-hybrid-skip", r.returncode == 0 and r.stdout.strip() == "target123",\n      f"{r.stdout.strip()[:40]} | {r.stderr.strip().splitlines()[-1] if r.stderr else \'\'}")\nos.unlink(WORDLIST)\n\n# --- 7. crack 掩码:CPU 与 GPU 双引擎(密钥 ab12 → ?l?l?d?d) ---\ncookie = make_serializer("ab12").dumps({"u": "x"})\nfor engine in ("cpu", "gpu", "auto"):\n    r = run("flask", "crack", "--cookie", cookie, "--mask", "?l?l?d?d", "--engine", engine)\n    check(f"crack-mask-{engine}", r.returncode == 0 and r.stdout.strip() == "ab12",\n          r.stderr.strip().splitlines()[-1] if r.stderr else "")\n\n# --- 8. --engine 校验:非法值拒绝;显式 gpu 超参报错不静默回退 ---\nr = run("flask", "crack", "--cookie", cookie, "--mask", "?l?l", "--engine", "gpuu")\ncheck("engine-invalid", r.returncode == 2)\nr = run("flask", "crack", "--cookie", cookie, "--mask", "?l?l",\n        "--engine", "gpu", "--salt", "s" * 40)\ncheck("engine-gpu-overlimit", r.returncode == 1 and "超限" in r.stderr,\n      r.stderr.strip()[:80])\n\n\n# --- 9. 交互模式:管道喂菜单答案(interactive 子命令不检查 tty,可测) ---\ndef run_stdin(stdin_text: str, *args: str) -> subprocess.CompletedProcess:\n    return subprocess.run([TOOL, *args], input=stdin_text,\n                          capture_output=True, text=True, encoding="utf-8")\n\n\ncookie = make_serializer("my-secret").dumps({"u": 1})\nr = run_stdin(f"1\\n{cookie}\\n0\\n", "interactive")\ncheck("interactive-decode", json.loads(r.stdout.strip()) == {"u": 1},\n      r.stdout.strip()[:80])\n\nr = run_stdin(\'3\\nmy-secret\\n{"u": 2}\\n\\nn\\n0\\n\', "interactive")\ntry:\n    back = ser.loads(r.stdout.strip())\n    ok, extra = back == {"u": 2}, ""\nexcept Exception as e:\n    ok, extra = False, f"{type(e).__name__}: {e}"\ncheck("interactive-sign", ok, extra)\n\n# 非 tty 无参数:不进交互,打印用法(rc 2)\nr = run_stdin("")\ncheck("noargs-non-tty", r.returncode == 2 and "用法" in r.stderr)\n\nsys.exit(1 if fails else 0)\n'
exec(compile(source, "tests/test_vectors.py", "exec"), {"__file__":str(Path("tests/test_vectors.py").resolve()),"__name__":"__main__"})
